update public.biblical_sources
set
  provider_version = 'historicos-v1-2026-08-02',
  license_notes = 'Síntesis editorial original de Vida Internacional, elaborada con asistencia de IA y pendiente de revisión académica especializada. No reproduce traducciones bíblicas protegidas.',
  attribution = 'Vida Internacional — corpus editorial asistido por IA; no sustituye comentarios críticos, léxicos ni revisión pastoral.',
  metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
    'coverage', 'canonical-index-pentateuch-historical-books',
    'generated_by_ai', true,
    'editorial_method', 'ai-assisted-contextual-synthesis',
    'review_level', 'project-editorial',
    'limitations', 'Contexto general y seccional; no sustituye crítica textual ni bibliografía académica especializada.'
  ),
  updated_at = now()
where slug = 'vida-contexto-editorial';

with source as (
  select id from public.biblical_sources where slug = 'vida-contexto-editorial'
),
data(
  slug, book_code, scope_kind, chapter_start, verse_start, chapter_end, verse_end,
  title, summary, historical_context, jewish_context, literary_context,
  authorial_intent, theological_reflection, interpretive_cautions,
  key_terms, people_groups, places
) as (
  values
  ('josue-perfil','JOS','book',1,NULL::smallint,24,NULL::smallint,'Josué: perfil histórico y literario','Josué relata la entrada de Israel en Canaán, la distribución de la tierra y la renovación del pacto. Presenta continuidad con Deuteronomio y pregunta cómo debe vivir el pueblo después del desierto.','El libro se sitúa literariamente en la transición entre la vida nómada del desierto y el establecimiento de Israel en Canaán. La relación entre el relato, la arqueología y la cronología de los asentamientos es debatida y no debe simplificarse.','En el canon judío Josué abre los Profetas Anteriores. Se lee como continuación de la Torá y como testimonio de la fidelidad de Dios, de la responsabilidad del pueblo y de la centralidad del pacto.','Combina discursos, narraciones de campaña, listas territoriales, relatos de pacto y ceremonias de memoria. El movimiento va desde el cruce del Jordán hasta la despedida de Josué.','Mostrar que la tierra es don y responsabilidad, que la obediencia al pacto importa y que la memoria de las obras de Dios debe orientar la vida comunitaria.','La fidelidad divina no elimina la responsabilidad humana. La comunidad es llamada a recordar, escoger y servir con integridad en medio de decisiones concretas.','Los relatos de guerra requieren atención al género, a la retórica antigua y al lugar del libro dentro del canon. No deben usarse para legitimar violencia religiosa moderna, conquista territorial contemporánea ni superioridad étnica.',ARRAY['tierra','pacto','herencia','obediencia','memoria']::text[],ARRAY['israelitas','cananeos']::text[],ARRAY['Jordán','Jericó','Canaán','Siquem']::text[]),
  ('josue-1-5','JOS','section',1,NULL::smallint,5,NULL::smallint,'Preparación y cruce del Jordán','Josué recibe la comisión de conducir al pueblo, los espías son protegidos por Rahab y la comunidad cruza el Jordán mediante una acción de memoria y consagración.','Esta unidad se desarrolla dentro del marco histórico general de Josué y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–5. El libro se sitúa literariamente en la transición entre la vida nómada del desierto y el establecimiento de Israel en Canaán. La relación entre el relato, la arqueología y la cronología de los asentamientos es debatida y no debe simplificarse.','En la lectura judía, esta sección contribuye a la memoria canónica de Josué y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. En el canon judío Josué abre los Profetas Anteriores. Se lee como continuación de la Torá y como testimonio de la fidelidad de Dios, de la responsabilidad del pueblo y de la centralidad del pacto.','La sección ocupa una función definida dentro de la composición de Josué. Combina discursos, narraciones de campaña, listas territoriales, relatos de pacto y ceremonias de memoria. El movimiento va desde el cruce del Jordán hasta la despedida de Josué.','Afirmar continuidad con Moisés y preparar al pueblo para entrar en la tierra con confianza, obediencia y memoria.','La fidelidad divina no elimina la responsabilidad humana. La comunidad es llamada a recordar, escoger y servir con integridad en medio de decisiones concretas.','Rahab no debe reducirse a un estereotipo moral; el relato destaca su decisión, su protección de los mensajeros y su incorporación al pueblo.',ARRAY['Josué','Rahab','Jordán','memorial']::text[],ARRAY['israelitas','habitantes de Jericó']::text[],ARRAY['Jordán','Jericó','Gilgal']::text[]),
  ('josue-6-12','JOS','section',6,NULL::smallint,12,NULL::smallint,'Campañas y conflictos en Canaán','Los relatos de Jericó, Hai, los gabaonitas y otras campañas presentan victoria, fracaso, juicio y alianzas dentro de una narrativa teológica de posesión de la tierra.','Esta unidad se desarrolla dentro del marco histórico general de Josué y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 6–12. El libro se sitúa literariamente en la transición entre la vida nómada del desierto y el establecimiento de Israel en Canaán. La relación entre el relato, la arqueología y la cronología de los asentamientos es debatida y no debe simplificarse.','En la lectura judía, esta sección contribuye a la memoria canónica de Josué y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. En el canon judío Josué abre los Profetas Anteriores. Se lee como continuación de la Torá y como testimonio de la fidelidad de Dios, de la responsabilidad del pueblo y de la centralidad del pacto.','La sección ocupa una función definida dentro de la composición de Josué. Combina discursos, narraciones de campaña, listas territoriales, relatos de pacto y ceremonias de memoria. El movimiento va desde el cruce del Jordán hasta la despedida de Josué.','Mostrar que el éxito no depende solo de estrategia militar, sino de fidelidad, discernimiento y responsabilidad ante el pacto.','La fidelidad divina no elimina la responsabilidad humana. La comunidad es llamada a recordar, escoger y servir con integridad en medio de decisiones concretas.','Las fórmulas de destrucción total pertenecen a la retórica bélica antigua y deben estudiarse junto con otros datos del mismo libro que muestran población cananea persistente.',ARRAY['Jericó','Hai','anatema','Gabaón']::text[],ARRAY['israelitas','cananeos','gabaonitas']::text[],ARRAY['Jericó','Hai','Gabaón']::text[]),
  ('josue-13-21','JOS','section',13,NULL::smallint,21,NULL::smallint,'Distribución de la tierra','La segunda mitad organiza territorios, fronteras, ciudades levíticas y ciudades de refugio, mostrando que la herencia se administra comunitariamente.','Esta unidad se desarrolla dentro del marco histórico general de Josué y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 13–21. El libro se sitúa literariamente en la transición entre la vida nómada del desierto y el establecimiento de Israel en Canaán. La relación entre el relato, la arqueología y la cronología de los asentamientos es debatida y no debe simplificarse.','En la lectura judía, esta sección contribuye a la memoria canónica de Josué y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. En el canon judío Josué abre los Profetas Anteriores. Se lee como continuación de la Torá y como testimonio de la fidelidad de Dios, de la responsabilidad del pueblo y de la centralidad del pacto.','La sección ocupa una función definida dentro de la composición de Josué. Combina discursos, narraciones de campaña, listas territoriales, relatos de pacto y ceremonias de memoria. El movimiento va desde el cruce del Jordán hasta la despedida de Josué.','Presentar la tierra como don ordenado, distribuido y sujeto a justicia, culto y cuidado comunitario.','La fidelidad divina no elimina la responsabilidad humana. La comunidad es llamada a recordar, escoger y servir con integridad en medio de decisiones concretas.','Las fronteras antiguas no deben proyectarse sin mediación sobre disputas políticas actuales; el texto responde a la identidad y memoria de Israel antiguo.',ARRAY['herencia','tribus','ciudades de refugio','levitas']::text[],ARRAY['tribus de Israel','levitas']::text[],ARRAY['Canaán','Silo']::text[]),
  ('josue-22-24','JOS','section',22,NULL::smallint,24,NULL::smallint,'Unidad tribal y renovación del pacto','Las tribus orientales explican su altar memorial y Josué concluye convocando al pueblo a escoger a quién servirá y renovar el pacto en Siquem.','Esta unidad se desarrolla dentro del marco histórico general de Josué y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 22–24. El libro se sitúa literariamente en la transición entre la vida nómada del desierto y el establecimiento de Israel en Canaán. La relación entre el relato, la arqueología y la cronología de los asentamientos es debatida y no debe simplificarse.','En la lectura judía, esta sección contribuye a la memoria canónica de Josué y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. En el canon judío Josué abre los Profetas Anteriores. Se lee como continuación de la Torá y como testimonio de la fidelidad de Dios, de la responsabilidad del pueblo y de la centralidad del pacto.','La sección ocupa una función definida dentro de la composición de Josué. Combina discursos, narraciones de campaña, listas territoriales, relatos de pacto y ceremonias de memoria. El movimiento va desde el cruce del Jordán hasta la despedida de Josué.','Llamar a una lealtad indivisa, conservar la unidad y transmitir la memoria del pacto a las generaciones siguientes.','La fidelidad divina no elimina la responsabilidad humana. La comunidad es llamada a recordar, escoger y servir con integridad en medio de decisiones concretas.','La frase “yo y mi casa” no autoriza coerción familiar; expresa una decisión de responsabilidad y testimonio dentro de una convocatoria comunitaria.',ARRAY['servicio','altar','testimonio','renovación del pacto']::text[],ARRAY['tribus de Israel']::text[],ARRAY['Siquem']::text[]),
  ('jueces-perfil','JDG','book',1,NULL::smallint,21,NULL::smallint,'Jueces: perfil histórico y literario','Jueces describe una época de inestabilidad política, religiosa y moral entre la ocupación de la tierra y la monarquía. Sus ciclos muestran opresión, clamor, liberación y recaída.','El marco corresponde a comunidades tribales sin gobierno central estable. Las narraciones conservan memorias de conflictos regionales y líderes locales, aunque su orden literario no funciona como una cronología moderna exhaustiva.','Jueces pertenece a los Profetas Anteriores y se lee como advertencia sobre la infidelidad del pacto, la fragmentación tribal y las consecuencias de abandonar la justicia de Dios.','El libro abre con un diagnóstico, desarrolla ciclos de jueces cada vez más problemáticos y termina con relatos de caos social. La repetición “cada uno hacía lo que bien le parecía” interpreta el deterioro.','Exponer cómo la idolatría, la violencia y la falta de liderazgo justo destruyen la vida común, aun cuando Dios muestra misericordia mediante libertadores imperfectos.','La gracia de Dios puede actuar en medio de comunidades quebradas, pero el texto no permite romantizar el desorden ni confundir carisma con carácter.','Muchos episodios describen violencia, abuso y decisiones moralmente corruptas sin aprobarlas. Las figuras de los jueces no deben tratarse como modelos completos de conducta.',ARRAY['jueces','ciclo','idolatría','opresión','liberación']::text[],ARRAY['tribus de Israel','cananeos','madianitas','filisteos']::text[],ARRAY['Canaán','Siquem','Gaza']::text[]),
  ('jueces-1-3','JDG','section',1,NULL::smallint,3,NULL::smallint,'Diagnóstico y primeros libertadores','La conquista queda incompleta, Israel adopta prácticas religiosas vecinas y aparecen Otoniel, Aod y Samgar como primeros libertadores.','Esta unidad se desarrolla dentro del marco histórico general de Jueces y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–3. El marco corresponde a comunidades tribales sin gobierno central estable. Las narraciones conservan memorias de conflictos regionales y líderes locales, aunque su orden literario no funciona como una cronología moderna exhaustiva.','En la lectura judía, esta sección contribuye a la memoria canónica de Jueces y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Jueces pertenece a los Profetas Anteriores y se lee como advertencia sobre la infidelidad del pacto, la fragmentación tribal y las consecuencias de abandonar la justicia de Dios.','La sección ocupa una función definida dentro de la composición de Jueces. El libro abre con un diagnóstico, desarrolla ciclos de jueces cada vez más problemáticos y termina con relatos de caos social. La repetición “cada uno hacía lo que bien le parecía” interpreta el deterioro.','Establecer el patrón de infidelidad, opresión, clamor y liberación que organizará el libro.','La gracia de Dios puede actuar en medio de comunidades quebradas, pero el texto no permite romantizar el desorden ni confundir carisma con carácter.','La discapacidad o la pertenencia étnica de los personajes no debe usarse como burla; el relato se concentra en la inversión de poder y la liberación.',ARRAY['infidelidad','clamor','liberación']::text[],ARRAY['israelitas','moabitas']::text[],ARRAY['Canaán']::text[]),
  ('jueces-4-9','JDG','section',4,NULL::smallint,9,NULL::smallint,'Débora, Gedeón y Abimelec','Débora y Barac enfrentan a Sísara; luego Gedeón libera a Israel pero su legado se deteriora, y Abimelec convierte la ambición dinástica en violencia.','Esta unidad se desarrolla dentro del marco histórico general de Jueces y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 4–9. El marco corresponde a comunidades tribales sin gobierno central estable. Las narraciones conservan memorias de conflictos regionales y líderes locales, aunque su orden literario no funciona como una cronología moderna exhaustiva.','En la lectura judía, esta sección contribuye a la memoria canónica de Jueces y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Jueces pertenece a los Profetas Anteriores y se lee como advertencia sobre la infidelidad del pacto, la fragmentación tribal y las consecuencias de abandonar la justicia de Dios.','La sección ocupa una función definida dentro de la composición de Jueces. El libro abre con un diagnóstico, desarrolla ciclos de jueces cada vez más problemáticos y termina con relatos de caos social. La repetición “cada uno hacía lo que bien le parecía” interpreta el deterioro.','Mostrar que Dios puede levantar liderazgo inesperado y que la búsqueda de poder sin pacto termina destruyendo a la comunidad.','La gracia de Dios puede actuar en medio de comunidades quebradas, pero el texto no permite romantizar el desorden ni confundir carisma con carácter.','El cántico de Débora es poesía de guerra antigua; no debe convertirse en permiso para celebrar violencia contemporánea. Gedeón debe leerse tanto por su fe como por sus contradicciones.',ARRAY['Débora','Barac','Gedeón','Abimelec']::text[],ARRAY['israelitas','cananeos','madianitas']::text[],ARRAY['Meguido','Siquem']::text[]),
  ('jueces-10-16','JDG','section',10,NULL::smallint,16,NULL::smallint,'Jefté y Sansón','Los ciclos de Jefté y Sansón muestran líderes dotados pero profundamente condicionados por votos imprudentes, rivalidades y deseos personales.','Esta unidad se desarrolla dentro del marco histórico general de Jueces y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 10–16. El marco corresponde a comunidades tribales sin gobierno central estable. Las narraciones conservan memorias de conflictos regionales y líderes locales, aunque su orden literario no funciona como una cronología moderna exhaustiva.','En la lectura judía, esta sección contribuye a la memoria canónica de Jueces y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Jueces pertenece a los Profetas Anteriores y se lee como advertencia sobre la infidelidad del pacto, la fragmentación tribal y las consecuencias de abandonar la justicia de Dios.','La sección ocupa una función definida dentro de la composición de Jueces. El libro abre con un diagnóstico, desarrolla ciclos de jueces cada vez más problemáticos y termina con relatos de caos social. La repetición “cada uno hacía lo que bien le parecía” interpreta el deterioro.','Evidenciar que una capacidad extraordinaria no sustituye la obediencia, la sabiduría ni el cuidado de los vulnerables.','La gracia de Dios puede actuar en medio de comunidades quebradas, pero el texto no permite romantizar el desorden ni confundir carisma con carácter.','El voto de Jefté no debe defenderse como mandato de Dios. La historia de Sansón tampoco legitima manipulación, violencia sexualizada ni venganza personal.',ARRAY['Jefté','voto','Sansón','nazareo']::text[],ARRAY['amonitas','filisteos','israelitas']::text[],ARRAY['Galaad','Gaza']::text[]),
  ('jueces-17-21','JDG','section',17,NULL::smallint,21,NULL::smallint,'Colapso religioso y social','Los relatos de Micaía, Dan, el levita y la guerra contra Benjamín muestran idolatría doméstica, abuso, tribalismo y casi exterminio interno.','Esta unidad se desarrolla dentro del marco histórico general de Jueces y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 17–21. El marco corresponde a comunidades tribales sin gobierno central estable. Las narraciones conservan memorias de conflictos regionales y líderes locales, aunque su orden literario no funciona como una cronología moderna exhaustiva.','En la lectura judía, esta sección contribuye a la memoria canónica de Jueces y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Jueces pertenece a los Profetas Anteriores y se lee como advertencia sobre la infidelidad del pacto, la fragmentación tribal y las consecuencias de abandonar la justicia de Dios.','La sección ocupa una función definida dentro de la composición de Jueces. El libro abre con un diagnóstico, desarrolla ciclos de jueces cada vez más problemáticos y termina con relatos de caos social. La repetición “cada uno hacía lo que bien le parecía” interpreta el deterioro.','Cerrar el libro demostrando que el caos religioso y la injusticia social están conectados y requieren liderazgo sometido a Dios.','La gracia de Dios puede actuar en medio de comunidades quebradas, pero el texto no permite romantizar el desorden ni confundir carisma con carácter.','Estos capítulos describen atrocidades para denunciarlas. No deben leerse como instrucciones ni minimizar el sufrimiento de las mujeres y comunidades afectadas.',ARRAY['idolatría','levita','Benjamín','caos']::text[],ARRAY['danitas','benjaminitas','tribus de Israel']::text[],ARRAY['Dan','Gabaa','Silo']::text[]),
  ('rut-perfil','RUT','book',1,NULL::smallint,4,NULL::smallint,'Rut: perfil histórico y literario','Rut narra cómo una viuda moabita acompaña a Noemí, encuentra protección y trabajo en los campos de Booz y llega a formar parte de la genealogía de David.','La historia se ambienta en el período de los jueces y refleja prácticas de cosecha, espigueo, parentesco, redención familiar y negociación pública en la puerta de la ciudad.','Rut se incluye entre los Escritos y se lee tradicionalmente en Shavuot. Destaca la bondad leal, la provisión, la conversión de Rut al pueblo de Israel y la genealogía davídica.','Es una narración breve cuidadosamente construida, con diálogos, contrastes entre vacío y plenitud, escenas de viaje, campo, era y puerta, y una genealogía final.','Mostrar la providencia de Dios mediante la fidelidad cotidiana, la hospitalidad, la justicia económica y la responsabilidad familiar.','La lealtad de Rut, la iniciativa de Noemí y la integridad de Booz revelan cómo Dios puede restaurar esperanza mediante decisiones concretas de amor y justicia.','No debe reducirse el libro a una receta romántica ni presentar a Rut como pasiva. Las prácticas de redención y matrimonio pertenecen a un contexto legal y familiar antiguo.',ARRAY['hesed','redentor','espigueo','Noemí','Booz']::text[],ARRAY['moabitas','israelitas']::text[],ARRAY['Moab','Belén']::text[]),
  ('rut-1-1','RUT','section',1,NULL::smallint,1,NULL::smallint,'Pérdida, regreso y lealtad','Noemí vuelve de Moab a Belén después de perder a su esposo e hijos; Rut decide acompañarla y adoptar su pueblo y su Dios.','Esta unidad se desarrolla dentro del marco histórico general de Rut y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–1. La historia se ambienta en el período de los jueces y refleja prácticas de cosecha, espigueo, parentesco, redención familiar y negociación pública en la puerta de la ciudad.','En la lectura judía, esta sección contribuye a la memoria canónica de Rut y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Rut se incluye entre los Escritos y se lee tradicionalmente en Shavuot. Destaca la bondad leal, la provisión, la conversión de Rut al pueblo de Israel y la genealogía davídica.','La sección ocupa una función definida dentro de la composición de Rut. Es una narración breve cuidadosamente construida, con diálogos, contrastes entre vacío y plenitud, escenas de viaje, campo, era y puerta, y una genealogía final.','Presentar la fidelidad de Rut y el dolor honesto de Noemí como punto de partida de una historia de restauración.','La lealtad de Rut, la iniciativa de Noemí y la integridad de Booz revelan cómo Dios puede restaurar esperanza mediante decisiones concretas de amor y justicia.','La decisión de Rut no debe utilizarse para exigir que una persona permanezca en situaciones dañinas; es un acto voluntario de lealtad en un contexto específico.',ARRAY['Rut','Noemí','lealtad','regreso']::text[],ARRAY['moabitas','israelitas']::text[],ARRAY['Moab','Belén']::text[]),
  ('rut-2-2','RUT','section',2,NULL::smallint,2,NULL::smallint,'Espigueo y protección','Rut trabaja detrás de los segadores y Booz aplica con generosidad las disposiciones de protección para pobres y extranjeros.','Esta unidad se desarrolla dentro del marco histórico general de Rut y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 2–2. La historia se ambienta en el período de los jueces y refleja prácticas de cosecha, espigueo, parentesco, redención familiar y negociación pública en la puerta de la ciudad.','En la lectura judía, esta sección contribuye a la memoria canónica de Rut y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Rut se incluye entre los Escritos y se lee tradicionalmente en Shavuot. Destaca la bondad leal, la provisión, la conversión de Rut al pueblo de Israel y la genealogía davídica.','La sección ocupa una función definida dentro de la composición de Rut. Es una narración breve cuidadosamente construida, con diálogos, contrastes entre vacío y plenitud, escenas de viaje, campo, era y puerta, y una genealogía final.','Mostrar que la providencia opera mediante estructuras de justicia, trabajo digno y hospitalidad hacia la persona vulnerable.','La lealtad de Rut, la iniciativa de Noemí y la integridad de Booz revelan cómo Dios puede restaurar esperanza mediante decisiones concretas de amor y justicia.','La generosidad de Booz no elimina la desigualdad social del contexto; el texto invita a proteger, no a romantizar la precariedad.',ARRAY['espigueo','Booz','protección','extranjero']::text[],ARRAY['moabitas','israelitas']::text[],ARRAY['Belén']::text[]),
  ('rut-3-4','RUT','section',3,NULL::smallint,4,NULL::smallint,'Redención familiar y nueva esperanza','Noemí orienta a Rut, Booz actúa públicamente como redentor y la historia culmina con una familia restaurada y una genealogía que llega a David.','Esta unidad se desarrolla dentro del marco histórico general de Rut y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 3–4. La historia se ambienta en el período de los jueces y refleja prácticas de cosecha, espigueo, parentesco, redención familiar y negociación pública en la puerta de la ciudad.','En la lectura judía, esta sección contribuye a la memoria canónica de Rut y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Rut se incluye entre los Escritos y se lee tradicionalmente en Shavuot. Destaca la bondad leal, la provisión, la conversión de Rut al pueblo de Israel y la genealogía davídica.','La sección ocupa una función definida dentro de la composición de Rut. Es una narración breve cuidadosamente construida, con diálogos, contrastes entre vacío y plenitud, escenas de viaje, campo, era y puerta, y una genealogía final.','Afirmar que la redención incluye responsabilidad legal, reputación pública, cuidado familiar y futuro comunitario.','La lealtad de Rut, la iniciativa de Noemí y la integridad de Booz revelan cómo Dios puede restaurar esperanza mediante decisiones concretas de amor y justicia.','La escena de la era contiene lenguaje culturalmente delicado y no debe interpretarse de manera sensacionalista. Booz protege el honor y procede mediante la puerta pública.',ARRAY['redentor','era','puerta','David']::text[],ARRAY['israelitas','moabitas']::text[],ARRAY['Belén']::text[]),
  ('1-samuel-perfil','1SA','book',1,NULL::smallint,31,NULL::smallint,'1 Samuel: perfil histórico y literario','1 Samuel narra la transición desde el liderazgo de jueces hasta la monarquía, siguiendo a Samuel, Saúl y el surgimiento de David.','El libro refleja la consolidación de Israel frente a los filisteos y la aparición de estructuras monárquicas. Los relatos combinan memoria histórica, evaluación profética y teología del pacto.','Forma parte de los Profetas Anteriores. Samuel aparece como profeta y juez; la petición de rey se evalúa con ambivalencia, reconociendo tanto la necesidad política como el peligro de sustituir el gobierno de Dios.','La narración entrelaza ciclos familiares, discursos proféticos, relatos de guerra y contrastes de carácter. Saúl y David se presentan mediante escenas paralelas que revelan obediencia, temor y poder.','Examinar qué clase de liderazgo honra a Dios y mostrar que la apariencia, el rango y el carisma no reemplazan la obediencia y la integridad.','Dios escucha el clamor, levanta líderes y también confronta el abuso del poder. La vida espiritual requiere escuchar, obedecer y rendir cuentas.','La elección de David no convierte todas sus acciones en ejemplares. Los textos sobre guerra, espíritu atormentador y consulta de muertos requieren lectura canónica cuidadosa y no autorizan prácticas dañinas.',ARRAY['Samuel','Saúl','David','monarquía','obediencia']::text[],ARRAY['israelitas','filisteos','amalecitas']::text[],ARRAY['Silo','Mizpa','Gabaá','Belén']::text[]),
  ('1-samuel-1-7','1SA','section',1,NULL::smallint,7,NULL::smallint,'Samuel y la renovación de Israel','El nacimiento y llamado de Samuel contrastan con la corrupción de los hijos de Elí; el arca es capturada y luego Israel se reúne para volver a Dios.','Esta unidad se desarrolla dentro del marco histórico general de 1 Samuel y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–7. El libro refleja la consolidación de Israel frente a los filisteos y la aparición de estructuras monárquicas. Los relatos combinan memoria histórica, evaluación profética y teología del pacto.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Samuel y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Forma parte de los Profetas Anteriores. Samuel aparece como profeta y juez; la petición de rey se evalúa con ambivalencia, reconociendo tanto la necesidad política como el peligro de sustituir el gobierno de Dios.','La sección ocupa una función definida dentro de la composición de 1 Samuel. La narración entrelaza ciclos familiares, discursos proféticos, relatos de guerra y contrastes de carácter. Saúl y David se presentan mediante escenas paralelas que revelan obediencia, temor y poder.','Mostrar que Dios escucha, llama y juzga, y que la renovación requiere abandonar la idolatría y recuperar una escucha responsable.','Dios escucha el clamor, levanta líderes y también confronta el abuso del poder. La vida espiritual requiere escuchar, obedecer y rendir cuentas.','La oración de Ana no debe usarse para culpar a personas con infertilidad ni prometer resultados idénticos; el texto cuenta una historia particular de dolor y respuesta.',ARRAY['Ana','Samuel','Elí','arca']::text[],ARRAY['israelitas','filisteos']::text[],ARRAY['Silo','Mizpa']::text[]),
  ('1-samuel-8-15','1SA','section',8,NULL::smallint,15,NULL::smallint,'Saúl y la crisis de la monarquía','Israel pide rey, Saúl es ungido y obtiene victorias, pero su liderazgo se deteriora por temor, impaciencia y desobediencia.','Esta unidad se desarrolla dentro del marco histórico general de 1 Samuel y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 8–15. El libro refleja la consolidación de Israel frente a los filisteos y la aparición de estructuras monárquicas. Los relatos combinan memoria histórica, evaluación profética y teología del pacto.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Samuel y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Forma parte de los Profetas Anteriores. Samuel aparece como profeta y juez; la petición de rey se evalúa con ambivalencia, reconociendo tanto la necesidad política como el peligro de sustituir el gobierno de Dios.','La sección ocupa una función definida dentro de la composición de 1 Samuel. La narración entrelaza ciclos familiares, discursos proféticos, relatos de guerra y contrastes de carácter. Saúl y David se presentan mediante escenas paralelas que revelan obediencia, temor y poder.','Evaluar la monarquía y enseñar que el poder legítimo permanece subordinado a la palabra de Dios y al bien del pueblo.','Dios escucha el clamor, levanta líderes y también confronta el abuso del poder. La vida espiritual requiere escuchar, obedecer y rendir cuentas.','La frase “obedecer es mejor que sacrificar” no niega el valor del culto, sino que denuncia su uso para encubrir desobediencia. Los relatos de guerra no legitiman violencia actual.',ARRAY['Saúl','rey','obediencia','sacrificio']::text[],ARRAY['israelitas','amonitas','amalecitas']::text[],ARRAY['Gabaá','Gilgal']::text[]),
  ('1-samuel-16-24','1SA','section',16,NULL::smallint,24,NULL::smallint,'David, Saúl y el uso del poder','David es ungido, vence a Goliat, sirve en la corte y huye de Saúl, mientras decide repetidamente no matar al rey.','Esta unidad se desarrolla dentro del marco histórico general de 1 Samuel y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 16–24. El libro refleja la consolidación de Israel frente a los filisteos y la aparición de estructuras monárquicas. Los relatos combinan memoria histórica, evaluación profética y teología del pacto.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Samuel y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Forma parte de los Profetas Anteriores. Samuel aparece como profeta y juez; la petición de rey se evalúa con ambivalencia, reconociendo tanto la necesidad política como el peligro de sustituir el gobierno de Dios.','La sección ocupa una función definida dentro de la composición de 1 Samuel. La narración entrelaza ciclos familiares, discursos proféticos, relatos de guerra y contrastes de carácter. Saúl y David se presentan mediante escenas paralelas que revelan obediencia, temor y poder.','Contrastar la confianza en Dios con el miedo posesivo y mostrar límites morales incluso frente a un adversario injusto.','Dios escucha el clamor, levanta líderes y también confronta el abuso del poder. La vida espiritual requiere escuchar, obedecer y rendir cuentas.','David no debe idealizarse; su prudencia y misericordia en estos capítulos conviven con ambición, violencia y decisiones discutibles en otros pasajes.',ARRAY['David','Goliat','Jonatán','ungido']::text[],ARRAY['israelitas','filisteos']::text[],ARRAY['Belén','Gat','En-gadi']::text[]),
  ('1-samuel-25-31','1SA','section',25,NULL::smallint,31,NULL::smallint,'Exilio de David y final de Saúl','Abigail evita una matanza, David vive entre filisteos y Saúl termina consultando a una médium antes de morir en batalla.','Esta unidad se desarrolla dentro del marco histórico general de 1 Samuel y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 25–31. El libro refleja la consolidación de Israel frente a los filisteos y la aparición de estructuras monárquicas. Los relatos combinan memoria histórica, evaluación profética y teología del pacto.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Samuel y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Forma parte de los Profetas Anteriores. Samuel aparece como profeta y juez; la petición de rey se evalúa con ambivalencia, reconociendo tanto la necesidad política como el peligro de sustituir el gobierno de Dios.','La sección ocupa una función definida dentro de la composición de 1 Samuel. La narración entrelaza ciclos familiares, discursos proféticos, relatos de guerra y contrastes de carácter. Saúl y David se presentan mediante escenas paralelas que revelan obediencia, temor y poder.','Cerrar el arco de Saúl mostrando el costo del aislamiento, la desobediencia y la búsqueda desesperada de control.','Dios escucha el clamor, levanta líderes y también confronta el abuso del poder. La vida espiritual requiere escuchar, obedecer y rendir cuentas.','La consulta de Saúl no aprueba la necromancia. La narración presenta la acción como señal de su alejamiento y desesperación.',ARRAY['Abigail','Nabal','Saúl','Endor']::text[],ARRAY['israelitas','filisteos']::text[],ARRAY['Carmelo','Siclag','Endor','Gilboa']::text[]),
  ('2-samuel-perfil','2SA','book',1,NULL::smallint,24,NULL::smallint,'2 Samuel: perfil histórico y literario','2 Samuel relata el reinado de David, la unificación del reino, el pacto davídico y las graves crisis familiares y políticas que siguen a su pecado y abuso de poder.','El libro se ubica en el surgimiento de una monarquía centralizada con Jerusalén como capital. Refleja guerra, administración, sucesión dinástica y tensiones tribales.','Como parte de los Profetas Anteriores, evalúa a David a la luz del pacto: recibe promesa y muestra fe, pero también es confrontado por el profeta Natán y su casa sufre consecuencias profundas.','La obra combina relatos de ascenso, listas, poemas, oráculos y una extensa narrativa de sucesión. El punto de giro se encuentra en el episodio de David, Betsabé y Urías.','Mostrar la fidelidad de Dios a su promesa y, al mismo tiempo, que ningún rey está por encima de la justicia, la verdad profética y la responsabilidad moral.','El liderazgo espiritual exige humildad, arrepentimiento y protección de los vulnerables. La gracia no borra las consecuencias ni impide llamar al poder por su nombre.','El relato de David y Betsabé implica abuso de poder y no debe presentarse como simple romance. La violencia familiar posterior tampoco debe espiritualizarse ni minimizar a las víctimas.',ARRAY['David','Jerusalén','pacto davídico','Natán','reino']::text[],ARRAY['israelitas','filisteos','amonitas']::text[],ARRAY['Hebrón','Jerusalén']::text[]),
  ('2-samuel-1-6','2SA','section',1,NULL::smallint,6,NULL::smallint,'Consolidación del reino y Jerusalén','David lamenta a Saúl y Jonatán, reina primero en Hebrón, unifica las tribus, toma Jerusalén y traslada el arca.','Esta unidad se desarrolla dentro del marco histórico general de 2 Samuel y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–6. El libro se ubica en el surgimiento de una monarquía centralizada con Jerusalén como capital. Refleja guerra, administración, sucesión dinástica y tensiones tribales.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Samuel y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Como parte de los Profetas Anteriores, evalúa a David a la luz del pacto: recibe promesa y muestra fe, pero también es confrontado por el profeta Natán y su casa sufre consecuencias profundas.','La sección ocupa una función definida dentro de la composición de 2 Samuel. La obra combina relatos de ascenso, listas, poemas, oráculos y una extensa narrativa de sucesión. El punto de giro se encuentra en el episodio de David, Betsabé y Urías.','Presentar la consolidación del reino bajo David y subrayar que el culto, la unidad y la justicia deben acompañar la autoridad política.','El liderazgo espiritual exige humildad, arrepentimiento y protección de los vulnerables. La gracia no borra las consecuencias ni impide llamar al poder por su nombre.','El ascenso de David incluye violencia y rivalidad; el texto no obliga a aprobar cada estrategia de sus seguidores.',ARRAY['Hebrón','Jerusalén','arca','unidad']::text[],ARRAY['judíos','israelitas','jebuseos']::text[],ARRAY['Hebrón','Jerusalén']::text[]),
  ('2-samuel-7-10','2SA','section',7,NULL::smallint,10,NULL::smallint,'Pacto davídico y expansión','Dios promete una casa a David, quien responde con oración; el reino se expande y David muestra bondad a Mefi-boset.','Esta unidad se desarrolla dentro del marco histórico general de 2 Samuel y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 7–10. El libro se ubica en el surgimiento de una monarquía centralizada con Jerusalén como capital. Refleja guerra, administración, sucesión dinástica y tensiones tribales.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Samuel y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Como parte de los Profetas Anteriores, evalúa a David a la luz del pacto: recibe promesa y muestra fe, pero también es confrontado por el profeta Natán y su casa sufre consecuencias profundas.','La sección ocupa una función definida dentro de la composición de 2 Samuel. La obra combina relatos de ascenso, listas, poemas, oráculos y una extensa narrativa de sucesión. El punto de giro se encuentra en el episodio de David, Betsabé y Urías.','Afirmar que la promesa real procede de la iniciativa divina y debe expresarse en administración, fidelidad y misericordia.','El liderazgo espiritual exige humildad, arrepentimiento y protección de los vulnerables. La gracia no borra las consecuencias ni impide llamar al poder por su nombre.','El pacto davídico no convierte la dinastía en poder sin límites; el resto del libro demuestra que el rey sigue bajo juicio moral.',ARRAY['casa','pacto','Mefi-boset','reino']::text[],ARRAY['israelitas','amonitas','arameos']::text[],ARRAY['Jerusalén']::text[]),
  ('2-samuel-11-12','2SA','section',11,NULL::smallint,12,NULL::smallint,'David, Betsabé y la confrontación profética','David toma a Betsabé, organiza la muerte de Urías y es confrontado por Natán. Reconoce su pecado, pero las consecuencias alcanzan a su casa.','Esta unidad se desarrolla dentro del marco histórico general de 2 Samuel y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 11–12. El libro se ubica en el surgimiento de una monarquía centralizada con Jerusalén como capital. Refleja guerra, administración, sucesión dinástica y tensiones tribales.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Samuel y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Como parte de los Profetas Anteriores, evalúa a David a la luz del pacto: recibe promesa y muestra fe, pero también es confrontado por el profeta Natán y su casa sufre consecuencias profundas.','La sección ocupa una función definida dentro de la composición de 2 Samuel. La obra combina relatos de ascenso, listas, poemas, oráculos y una extensa narrativa de sucesión. El punto de giro se encuentra en el episodio de David, Betsabé y Urías.','Declarar que el rey no está por encima de la ley y que la palabra profética debe proteger la verdad frente al poder.','El liderazgo espiritual exige humildad, arrepentimiento y protección de los vulnerables. La gracia no borra las consecuencias ni impide llamar al poder por su nombre.','Betsabé no debe ser culpada por el abuso de David. El arrepentimiento del rey no elimina el daño ni obliga a ignorar justicia y reparación.',ARRAY['Betsabé','Urías','Natán','arrepentimiento']::text[],ARRAY['israelitas']::text[],ARRAY['Jerusalén']::text[]),
  ('2-samuel-13-20','2SA','section',13,NULL::smallint,20,NULL::smallint,'Violencia familiar y rebelión de Absalón','La casa de David se fractura mediante la agresión contra Tamar, la venganza de Absalón, la rebelión y nuevas tensiones tribales.','Esta unidad se desarrolla dentro del marco histórico general de 2 Samuel y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 13–20. El libro se ubica en el surgimiento de una monarquía centralizada con Jerusalén como capital. Refleja guerra, administración, sucesión dinástica y tensiones tribales.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Samuel y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Como parte de los Profetas Anteriores, evalúa a David a la luz del pacto: recibe promesa y muestra fe, pero también es confrontado por el profeta Natán y su casa sufre consecuencias profundas.','La sección ocupa una función definida dentro de la composición de 2 Samuel. La obra combina relatos de ascenso, listas, poemas, oráculos y una extensa narrativa de sucesión. El punto de giro se encuentra en el episodio de David, Betsabé y Urías.','Mostrar cómo el abuso no confrontado, la pasividad del liderazgo y la ambición política multiplican el sufrimiento.','El liderazgo espiritual exige humildad, arrepentimiento y protección de los vulnerables. La gracia no borra las consecuencias ni impide llamar al poder por su nombre.','Tamar debe ser reconocida como víctima cuya voz denuncia la injusticia. El texto no debe usarse para justificar silencio familiar ni reconciliación sin protección.',ARRAY['Tamar','Amnón','Absalón','rebelión']::text[],ARRAY['israelitas','judíos']::text[],ARRAY['Jerusalén','Mahánayim']::text[]),
  ('2-samuel-21-24','2SA','section',21,NULL::smallint,24,NULL::smallint,'Apéndices sobre justicia, memoria y culto','Relatos, listas, poemas y el censo final resumen la trayectoria de David y terminan con la compra de la era donde se ofrece sacrificio.','Esta unidad se desarrolla dentro del marco histórico general de 2 Samuel y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 21–24. El libro se ubica en el surgimiento de una monarquía centralizada con Jerusalén como capital. Refleja guerra, administración, sucesión dinástica y tensiones tribales.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Samuel y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Como parte de los Profetas Anteriores, evalúa a David a la luz del pacto: recibe promesa y muestra fe, pero también es confrontado por el profeta Natán y su casa sufre consecuencias profundas.','La sección ocupa una función definida dentro de la composición de 2 Samuel. La obra combina relatos de ascenso, listas, poemas, oráculos y una extensa narrativa de sucesión. El punto de giro se encuentra en el episodio de David, Betsabé y Urías.','Invitar a evaluar el reinado mediante memoria, justicia, dependencia de Dios y responsabilidad por decisiones públicas.','El liderazgo espiritual exige humildad, arrepentimiento y protección de los vulnerables. La gracia no borra las consecuencias ni impide llamar al poder por su nombre.','Los apéndices no están ordenados como simple cronología. El censo y la plaga plantean preguntas difíciles sobre responsabilidad colectiva que requieren lectura cuidadosa.',ARRAY['valientes','censo','era','sacrificio']::text[],ARRAY['israelitas','gabaonitas']::text[],ARRAY['Jerusalén']::text[]),
  ('1-reyes-perfil','1KI','book',1,NULL::smallint,22,NULL::smallint,'1 Reyes: perfil histórico y literario','1 Reyes sigue la sucesión de David, el reinado de Salomón, la construcción del templo, la división del reino y el ministerio profético de Elías.','El libro abarca la monarquía unida tardía y el surgimiento de los reinos de Israel y Judá. Refleja administración real, comercio, tributación, culto estatal y conflictos regionales.','En los Profetas Anteriores, los reyes son evaluados principalmente por fidelidad al pacto y al culto de YHWH. El templo es central, pero nunca sustituye la obediencia.','Combina narración de corte, discursos, fórmulas regias, relatos proféticos y evaluación teológica. La división del reino organiza la segunda mitad.','Demostrar que sabiduría, riqueza y estructuras religiosas no preservan a una nación cuando el liderazgo abandona la justicia y la lealtad a Dios.','El don y el éxito requieren vigilancia espiritual. La voz profética recuerda que el poder debe escuchar la verdad, proteger al vulnerable y rechazar la idolatría.','Salomón no debe idealizarse solo por su sabiduría; el libro también critica acumulación, trabajo forzado y alianzas idolátricas. Los conflictos de Elías no autorizan violencia religiosa moderna.',ARRAY['Salomón','templo','reino dividido','Elías','idolatría']::text[],ARRAY['israelitas','judíos','fenicios','arameos']::text[],ARRAY['Jerusalén','Samaria','Carmelo']::text[]),
  ('1-reyes-1-4','1KI','section',1,NULL::smallint,4,NULL::smallint,'Sucesión y sabiduría de Salomón','Salomón accede al trono en medio de tensiones sucesorias, pide sabiduría y organiza la administración del reino.','Esta unidad se desarrolla dentro del marco histórico general de 1 Reyes y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–4. El libro abarca la monarquía unida tardía y el surgimiento de los reinos de Israel y Judá. Refleja administración real, comercio, tributación, culto estatal y conflictos regionales.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Reyes y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. En los Profetas Anteriores, los reyes son evaluados principalmente por fidelidad al pacto y al culto de YHWH. El templo es central, pero nunca sustituye la obediencia.','La sección ocupa una función definida dentro de la composición de 1 Reyes. Combina narración de corte, discursos, fórmulas regias, relatos proféticos y evaluación teológica. La división del reino organiza la segunda mitad.','Presentar la sabiduría como don para gobernar con justicia y mostrar las responsabilidades y riesgos del poder consolidado.','El don y el éxito requieren vigilancia espiritual. La voz profética recuerda que el poder debe escuchar la verdad, proteger al vulnerable y rechazar la idolatría.','La resolución sobre las dos mujeres no es un modelo legal general, sino una narración que demuestra discernimiento en un caso particular.',ARRAY['Salomón','sabiduría','justicia','administración']::text[],ARRAY['israelitas']::text[],ARRAY['Jerusalén']::text[]),
  ('1-reyes-5-11','1KI','section',5,NULL::smallint,11,NULL::smallint,'Templo, gloria y declive de Salomón','Salomón construye y dedica el templo, alcanza fama internacional y luego desvía su corazón mediante alianzas, acumulación e idolatría.','Esta unidad se desarrolla dentro del marco histórico general de 1 Reyes y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 5–11. El libro abarca la monarquía unida tardía y el surgimiento de los reinos de Israel y Judá. Refleja administración real, comercio, tributación, culto estatal y conflictos regionales.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Reyes y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. En los Profetas Anteriores, los reyes son evaluados principalmente por fidelidad al pacto y al culto de YHWH. El templo es central, pero nunca sustituye la obediencia.','La sección ocupa una función definida dentro de la composición de 1 Reyes. Combina narración de corte, discursos, fórmulas regias, relatos proféticos y evaluación teológica. La división del reino organiza la segunda mitad.','Afirmar que la presencia de Dios y la oración del templo exigen fidelidad continua; ningún logro religioso compensa la desobediencia.','El don y el éxito requieren vigilancia espiritual. La voz profética recuerda que el poder debe escuchar la verdad, proteger al vulnerable y rechazar la idolatría.','Las mujeres extranjeras no deben convertirse en chivo expiatorio; el texto responsabiliza a Salomón por sus decisiones políticas y religiosas.',ARRAY['templo','dedicación','reina de Sabá','idolatría']::text[],ARRAY['israelitas','fenicios']::text[],ARRAY['Jerusalén']::text[]),
  ('1-reyes-12-16','1KI','section',12,NULL::smallint,16,NULL::smallint,'División del reino y nuevas dinastías','Roboam endurece las cargas, Jeroboam establece santuarios alternativos y ambos reinos entran en ciclos de inestabilidad e idolatría.','Esta unidad se desarrolla dentro del marco histórico general de 1 Reyes y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 12–16. El libro abarca la monarquía unida tardía y el surgimiento de los reinos de Israel y Judá. Refleja administración real, comercio, tributación, culto estatal y conflictos regionales.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Reyes y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. En los Profetas Anteriores, los reyes son evaluados principalmente por fidelidad al pacto y al culto de YHWH. El templo es central, pero nunca sustituye la obediencia.','La sección ocupa una función definida dentro de la composición de 1 Reyes. Combina narración de corte, discursos, fórmulas regias, relatos proféticos y evaluación teológica. La división del reino organiza la segunda mitad.','Explicar que el abuso económico, la ambición política y la manipulación del culto fracturan la comunidad.','El don y el éxito requieren vigilancia espiritual. La voz profética recuerda que el poder debe escuchar la verdad, proteger al vulnerable y rechazar la idolatría.','La división no debe reducirse a un único culpable; el relato conecta decisiones humanas, historia previa y juicio profético.',ARRAY['Roboam','Jeroboam','Betel','reino dividido']::text[],ARRAY['israelitas','judíos']::text[],ARRAY['Siquem','Betel','Dan']::text[]),
  ('1-reyes-17-22','1KI','section',17,NULL::smallint,22,NULL::smallint,'Elías y la confrontación con Acab','Elías anuncia sequía, es sostenido durante la crisis, confronta el culto a Baal y denuncia a Acab por el caso de Nabot.','Esta unidad se desarrolla dentro del marco histórico general de 1 Reyes y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 17–22. El libro abarca la monarquía unida tardía y el surgimiento de los reinos de Israel y Judá. Refleja administración real, comercio, tributación, culto estatal y conflictos regionales.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Reyes y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. En los Profetas Anteriores, los reyes son evaluados principalmente por fidelidad al pacto y al culto de YHWH. El templo es central, pero nunca sustituye la obediencia.','La sección ocupa una función definida dentro de la composición de 1 Reyes. Combina narración de corte, discursos, fórmulas regias, relatos proféticos y evaluación teológica. La división del reino organiza la segunda mitad.','Mostrar que Dios sostiene vida, confronta idolatría y exige justicia incluso al rey más poderoso.','El don y el éxito requieren vigilancia espiritual. La voz profética recuerda que el poder debe escuchar la verdad, proteger al vulnerable y rechazar la idolatría.','El Carmelo es un juicio narrativo dentro de un conflicto antiguo; no autoriza persecución religiosa. Nabot debe leerse como víctima de abuso estatal.',ARRAY['Elías','Acab','Jezabel','Nabot','Carmelo']::text[],ARRAY['israelitas','fenicios']::text[],ARRAY['Carmelo','Jezreel','Samaria']::text[]),
  ('2-reyes-perfil','2KI','book',1,NULL::smallint,25,NULL::smallint,'2 Reyes: perfil histórico y literario','2 Reyes continúa la historia de los reinos hasta la caída de Samaria y Jerusalén, destacando los ministerios de Eliseo, las reformas y el exilio.','El libro se relaciona con el ascenso de Asiria y Babilonia, la caída del reino del norte en 722 a. C. aproximadamente y la destrucción de Jerusalén en 586 a. C. aproximadamente.','Como cierre de los Profetas Anteriores, interpreta el exilio a la luz de siglos de infidelidad, pero conserva señales de palabra profética, reforma y esperanza dinástica.','Alterna relatos proféticos con fórmulas regias y evaluaciones de reyes. La caída de Samaria y la de Jerusalén forman dos grandes desenlaces.','Explicar que el juicio histórico no fue arbitrario, sino consecuencia acumulada de idolatría, injusticia y rechazo de advertencias proféticas.','La paciencia de Dios no equivale a indiferencia. La reforma auténtica requiere más que símbolos y debe alcanzar prácticas, estructuras y memoria comunitaria.','Los relatos de juicio no deben emplearse para afirmar que toda tragedia actual es castigo directo. Las narraciones de milagros y violencia profética requieren lectura contextual.',ARRAY['Eliseo','Asiria','Babilonia','reforma','exilio']::text[],ARRAY['israelitas','judíos','asirios','babilonios','arameos']::text[],ARRAY['Samaria','Jerusalén']::text[]),
  ('2-reyes-1-8','2KI','section',1,NULL::smallint,8,NULL::smallint,'Eliseo y la palabra profética','La transición de Elías a Eliseo introduce relatos de sanidad, provisión, guerra y restauración que muestran la palabra de Dios activa en la vida pública y cotidiana.','Esta unidad se desarrolla dentro del marco histórico general de 2 Reyes y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–8. El libro se relaciona con el ascenso de Asiria y Babilonia, la caída del reino del norte en 722 a. C. aproximadamente y la destrucción de Jerusalén en 586 a. C. aproximadamente.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Reyes y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Como cierre de los Profetas Anteriores, interpreta el exilio a la luz de siglos de infidelidad, pero conserva señales de palabra profética, reforma y esperanza dinástica.','La sección ocupa una función definida dentro de la composición de 2 Reyes. Alterna relatos proféticos con fórmulas regias y evaluaciones de reyes. La caída de Samaria y la de Jerusalén forman dos grandes desenlaces.','Afirmar que el poder de Dios alcanza a personas vulnerables y extranjeras, y que la palabra profética confronta tanto necesidad como arrogancia.','La paciencia de Dios no equivale a indiferencia. La reforma auténtica requiere más que símbolos y debe alcanzar prácticas, estructuras y memoria comunitaria.','Los milagros no deben convertirse en fórmulas garantizadas. La historia de Naamán rechaza la compra del don y confronta orgullo y codicia.',ARRAY['Eliseo','Naamán','sanidad','provisión']::text[],ARRAY['israelitas','arameos']::text[],ARRAY['Jordán','Samaria']::text[]),
  ('2-reyes-9-17','2KI','section',9,NULL::smallint,17,NULL::smallint,'Revoluciones y caída de Samaria','Jehú elimina la casa de Acab pero mantiene otros pecados; la inestabilidad continúa hasta que Asiria conquista Samaria y deporta población.','Esta unidad se desarrolla dentro del marco histórico general de 2 Reyes y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 9–17. El libro se relaciona con el ascenso de Asiria y Babilonia, la caída del reino del norte en 722 a. C. aproximadamente y la destrucción de Jerusalén en 586 a. C. aproximadamente.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Reyes y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Como cierre de los Profetas Anteriores, interpreta el exilio a la luz de siglos de infidelidad, pero conserva señales de palabra profética, reforma y esperanza dinástica.','La sección ocupa una función definida dentro de la composición de 2 Reyes. Alterna relatos proféticos con fórmulas regias y evaluaciones de reyes. La caída de Samaria y la de Jerusalén forman dos grandes desenlaces.','Interpretar el colapso del norte como resultado acumulado de idolatría, violencia política y resistencia persistente a los profetas.','La paciencia de Dios no equivale a indiferencia. La reforma auténtica requiere más que símbolos y debe alcanzar prácticas, estructuras y memoria comunitaria.','El lenguaje de juicio no debe borrar los factores imperiales ni el sufrimiento de civiles. Tampoco debe utilizarse para demonizar pueblos modernos.',ARRAY['Jehú','Samaria','Asiria','exilio']::text[],ARRAY['israelitas','asirios']::text[],ARRAY['Samaria']::text[]),
  ('2-reyes-18-20','2KI','section',18,NULL::smallint,20,NULL::smallint,'Ezequías, Asiria y liberación','Ezequías reforma el culto, Jerusalén enfrenta la amenaza de Senaquerib y el rey experimenta enfermedad, oración y una visita babilónica.','Esta unidad se desarrolla dentro del marco histórico general de 2 Reyes y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 18–20. El libro se relaciona con el ascenso de Asiria y Babilonia, la caída del reino del norte en 722 a. C. aproximadamente y la destrucción de Jerusalén en 586 a. C. aproximadamente.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Reyes y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Como cierre de los Profetas Anteriores, interpreta el exilio a la luz de siglos de infidelidad, pero conserva señales de palabra profética, reforma y esperanza dinástica.','La sección ocupa una función definida dentro de la composición de 2 Reyes. Alterna relatos proféticos con fórmulas regias y evaluaciones de reyes. La caída de Samaria y la de Jerusalén forman dos grandes desenlaces.','Mostrar la importancia de confiar en Dios frente a propaganda imperial y la necesidad de humildad después de la liberación.','La paciencia de Dios no equivale a indiferencia. La reforma auténtica requiere más que símbolos y debe alcanzar prácticas, estructuras y memoria comunitaria.','La liberación de Jerusalén en esta ocasión no establece que toda ciudad fiel será preservada de guerra; la propia narración avanza hacia un juicio posterior.',ARRAY['Ezequías','Senaquerib','Asiria','oración']::text[],ARRAY['judíos','asirios']::text[],ARRAY['Jerusalén']::text[]),
  ('2-reyes-21-25','2KI','section',21,NULL::smallint,25,NULL::smallint,'De Manasés al exilio de Judá','Después de la larga influencia de Manasés, Josías reforma el culto, pero Babilonia finalmente destruye Jerusalén y lleva a Judá al exilio.','Esta unidad se desarrolla dentro del marco histórico general de 2 Reyes y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 21–25. El libro se relaciona con el ascenso de Asiria y Babilonia, la caída del reino del norte en 722 a. C. aproximadamente y la destrucción de Jerusalén en 586 a. C. aproximadamente.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Reyes y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Como cierre de los Profetas Anteriores, interpreta el exilio a la luz de siglos de infidelidad, pero conserva señales de palabra profética, reforma y esperanza dinástica.','La sección ocupa una función definida dentro de la composición de 2 Reyes. Alterna relatos proféticos con fórmulas regias y evaluaciones de reyes. La caída de Samaria y la de Jerusalén forman dos grandes desenlaces.','Explicar la profundidad del deterioro y mostrar que una reforma tardía puede ser real sin borrar automáticamente consecuencias históricas acumuladas.','La paciencia de Dios no equivale a indiferencia. La reforma auténtica requiere más que símbolos y debe alcanzar prácticas, estructuras y memoria comunitaria.','Josías no debe usarse para sostener que un líder individual puede resolver todo sin transformación social duradera. El exilio no anula toda esperanza.',ARRAY['Manasés','Josías','Babilonia','exilio']::text[],ARRAY['judíos','babilonios']::text[],ARRAY['Jerusalén','Babilonia']::text[]),
  ('1-cronicas-perfil','1CH','book',1,NULL::smallint,29,NULL::smallint,'1 Crónicas: perfil histórico y literario','1 Crónicas vuelve a narrar la historia desde Adán hasta David, con énfasis en genealogías, culto, levitas, Jerusalén y preparación del templo.','La obra suele relacionarse con la comunidad posterior al exilio, que necesitaba reconstruir identidad, continuidad genealógica y vida de culto alrededor de Jerusalén.','Crónicas pertenece a los Escritos. Relee tradiciones anteriores para fortalecer a una comunidad restaurada, vinculando pasado, templo, oración y responsabilidad presente.','Comienza con amplias genealogías y luego concentra la narración en David. Selecciona y reorganiza materiales para destacar culto, unidad y preparación del templo.','Afirmar que la comunidad posterior al exilio pertenece a la historia del pacto y puede renovar su vida mediante memoria, culto ordenado y búsqueda de Dios.','La memoria espiritual no es nostalgia; organiza identidad, servicio y esperanza. Los dones y responsabilidades de muchas familias sostienen el bien común.','Las diferencias con Samuel y Reyes deben estudiarse como relectura teológica, no como simple error. El énfasis positivo en David no borra sus fallas conocidas por el canon.',ARRAY['genealogías','David','levitas','templo','culto']::text[],ARRAY['tribus de Israel','levitas','judíos']::text[],ARRAY['Jerusalén']::text[]),
  ('1-cronicas-1-9','1CH','section',1,NULL::smallint,9,NULL::smallint,'Genealogías e identidad restaurada','Las genealogías recorren desde Adán hasta familias y tribus de Israel, culminando con habitantes de Jerusalén después del exilio.','Esta unidad se desarrolla dentro del marco histórico general de 1 Crónicas y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–9. La obra suele relacionarse con la comunidad posterior al exilio, que necesitaba reconstruir identidad, continuidad genealógica y vida de culto alrededor de Jerusalén.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Crónicas y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Crónicas pertenece a los Escritos. Relee tradiciones anteriores para fortalecer a una comunidad restaurada, vinculando pasado, templo, oración y responsabilidad presente.','La sección ocupa una función definida dentro de la composición de 1 Crónicas. Comienza con amplias genealogías y luego concentra la narración en David. Selecciona y reorganiza materiales para destacar culto, unidad y preparación del templo.','Conectar a la comunidad restaurada con la historia amplia de la humanidad, las tribus y el servicio del templo.','La memoria espiritual no es nostalgia; organiza identidad, servicio y esperanza. Los dones y responsabilidades de muchas familias sostienen el bien común.','Las genealogías son selectivas y teológicas; no deben exigirse como registros civiles exhaustivos ni usarse para afirmar superioridad de linaje.',ARRAY['genealogía','tribus','levitas','Jerusalén']::text[],ARRAY['tribus de Israel','levitas','judíos']::text[],ARRAY['Jerusalén']::text[]),
  ('1-cronicas-10-16','1CH','section',10,NULL::smallint,16,NULL::smallint,'David, Jerusalén y el arca','Tras la muerte de Saúl, David recibe apoyo tribal, toma Jerusalén y organiza el traslado del arca con participación levítica y canto.','Esta unidad se desarrolla dentro del marco histórico general de 1 Crónicas y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 10–16. La obra suele relacionarse con la comunidad posterior al exilio, que necesitaba reconstruir identidad, continuidad genealógica y vida de culto alrededor de Jerusalén.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Crónicas y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Crónicas pertenece a los Escritos. Relee tradiciones anteriores para fortalecer a una comunidad restaurada, vinculando pasado, templo, oración y responsabilidad presente.','La sección ocupa una función definida dentro de la composición de 1 Crónicas. Comienza con amplias genealogías y luego concentra la narración en David. Selecciona y reorganiza materiales para destacar culto, unidad y preparación del templo.','Presentar la unidad alrededor de David y el culto como fundamentos de identidad comunitaria.','La memoria espiritual no es nostalgia; organiza identidad, servicio y esperanza. Los dones y responsabilidades de muchas familias sostienen el bien común.','La muerte de Uza exige considerar instrucciones cultuales y el desarrollo narrativo; no debe usarse para fomentar temor supersticioso ni justificar abuso religioso.',ARRAY['David','arca','levitas','canto']::text[],ARRAY['israelitas','levitas']::text[],ARRAY['Jerusalén']::text[]),
  ('1-cronicas-17-22','1CH','section',17,NULL::smallint,22,NULL::smallint,'Promesa, victorias y preparación del templo','Dios confirma la promesa a David; el rey organiza recursos y, después del censo, identifica el lugar donde se preparará el templo.','Esta unidad se desarrolla dentro del marco histórico general de 1 Crónicas y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 17–22. La obra suele relacionarse con la comunidad posterior al exilio, que necesitaba reconstruir identidad, continuidad genealógica y vida de culto alrededor de Jerusalén.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Crónicas y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Crónicas pertenece a los Escritos. Relee tradiciones anteriores para fortalecer a una comunidad restaurada, vinculando pasado, templo, oración y responsabilidad presente.','La sección ocupa una función definida dentro de la composición de 1 Crónicas. Comienza con amplias genealogías y luego concentra la narración en David. Selecciona y reorganiza materiales para destacar culto, unidad y preparación del templo.','Vincular la promesa davídica con la responsabilidad de preparar una casa de culto que otro construirá.','La memoria espiritual no es nostalgia; organiza identidad, servicio y esperanza. Los dones y responsabilidades de muchas familias sostienen el bien común.','El énfasis en preparación no convierte riqueza o construcción en medida automática de fidelidad. El censo sigue siendo una advertencia sobre orgullo y poder.',ARRAY['pacto davídico','censo','templo','preparación']::text[],ARRAY['israelitas']::text[],ARRAY['Jerusalén']::text[]),
  ('1-cronicas-23-29','1CH','section',23,NULL::smallint,29,NULL::smallint,'Organización del servicio y sucesión','David distribuye responsabilidades de levitas, sacerdotes, músicos, porteros y oficiales, entrega planes y encarga a Salomón la obra.','Esta unidad se desarrolla dentro del marco histórico general de 1 Crónicas y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 23–29. La obra suele relacionarse con la comunidad posterior al exilio, que necesitaba reconstruir identidad, continuidad genealógica y vida de culto alrededor de Jerusalén.','En la lectura judía, esta sección contribuye a la memoria canónica de 1 Crónicas y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Crónicas pertenece a los Escritos. Relee tradiciones anteriores para fortalecer a una comunidad restaurada, vinculando pasado, templo, oración y responsabilidad presente.','La sección ocupa una función definida dentro de la composición de 1 Crónicas. Comienza con amplias genealogías y luego concentra la narración en David. Selecciona y reorganiza materiales para destacar culto, unidad y preparación del templo.','Mostrar que el culto y el liderazgo requieren organización, generosidad, colaboración y sucesión responsable.','La memoria espiritual no es nostalgia; organiza identidad, servicio y esperanza. Los dones y responsabilidades de muchas familias sostienen el bien común.','Los modelos organizativos de Crónicas responden a su contexto y no deben copiarse mecánicamente como única estructura válida para toda comunidad.',ARRAY['levitas','sacerdotes','músicos','Salomón']::text[],ARRAY['levitas','sacerdotes','israelitas']::text[],ARRAY['Jerusalén']::text[]),
  ('2-cronicas-perfil','2CH','book',1,NULL::smallint,36,NULL::smallint,'2 Crónicas: perfil histórico y literario','2 Crónicas narra desde Salomón hasta el exilio, concentrándose en el templo, los reyes de Judá, reformas, oración, juicio y posibilidad de restauración.','La obra relee la monarquía desde una perspectiva posterior al exilio. Su audiencia conocía la pérdida del templo y necesitaba comprender continuidad, responsabilidad y esperanza.','Dentro de los Escritos, Crónicas cierra en muchas ordenaciones del canon hebreo con el decreto de Ciro, abriendo una puerta de regreso y reconstrucción.','Presenta discursos, oraciones, relatos de batalla, reformas y evaluaciones regias. Omite gran parte del reino del norte salvo cuando se relaciona con Judá.','Enseñar que buscar a Dios, escuchar a los profetas y ordenar el culto puede traer renovación, mientras la dureza persistente conduce a ruina.','La reforma necesita memoria, enseñanza, justicia y perseverancia. Aun después del fracaso, la historia puede abrirse a una nueva oportunidad.','La relación inmediata entre conducta y prosperidad en algunos episodios pertenece a la teología narrativa de la obra y no debe convertirse en fórmula universal de riqueza o salud.',ARRAY['Salomón','templo','reforma','Judá','Ciro']::text[],ARRAY['judíos','levitas','asirios','babilonios','persas']::text[],ARRAY['Jerusalén']::text[]),
  ('2-cronicas-1-9','2CH','section',1,NULL::smallint,9,NULL::smallint,'Salomón y la dedicación del templo','Salomón pide sabiduría, construye el templo y lo dedica con oración, sacrificio y celebración nacional.','Esta unidad se desarrolla dentro del marco histórico general de 2 Crónicas y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–9. La obra relee la monarquía desde una perspectiva posterior al exilio. Su audiencia conocía la pérdida del templo y necesitaba comprender continuidad, responsabilidad y esperanza.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Crónicas y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Dentro de los Escritos, Crónicas cierra en muchas ordenaciones del canon hebreo con el decreto de Ciro, abriendo una puerta de regreso y reconstrucción.','La sección ocupa una función definida dentro de la composición de 2 Crónicas. Presenta discursos, oraciones, relatos de batalla, reformas y evaluaciones regias. Omite gran parte del reino del norte salvo cuando se relaciona con Judá.','Presentar el templo como lugar de oración, perdón y encuentro, subordinado a la búsqueda sincera de Dios.','La reforma necesita memoria, enseñanza, justicia y perseverancia. Aun después del fracaso, la historia puede abrirse a una nueva oportunidad.','La promesa de sanidad de la tierra en 7:14 se dirige al pueblo del pacto en un contexto específico; no debe aplicarse como fórmula política automática a cualquier nación moderna.',ARRAY['Salomón','templo','oración','gloria']::text[],ARRAY['judíos','levitas']::text[],ARRAY['Jerusalén']::text[]),
  ('2-cronicas-10-20','2CH','section',10,NULL::smallint,20,NULL::smallint,'Primeros reyes y búsqueda de Dios','Roboam, Abías, Asa y Josafat enfrentan divisiones y amenazas; la narración destaca momentos de reforma, enseñanza y dependencia de Dios.','Esta unidad se desarrolla dentro del marco histórico general de 2 Crónicas y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 10–20. La obra relee la monarquía desde una perspectiva posterior al exilio. Su audiencia conocía la pérdida del templo y necesitaba comprender continuidad, responsabilidad y esperanza.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Crónicas y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Dentro de los Escritos, Crónicas cierra en muchas ordenaciones del canon hebreo con el decreto de Ciro, abriendo una puerta de regreso y reconstrucción.','La sección ocupa una función definida dentro de la composición de 2 Crónicas. Presenta discursos, oraciones, relatos de batalla, reformas y evaluaciones regias. Omite gran parte del reino del norte salvo cuando se relaciona con Judá.','Mostrar que la seguridad de Judá depende de buscar a Dios, escuchar consejo y ordenar la justicia, no solo de alianzas militares.','La reforma necesita memoria, enseñanza, justicia y perseverancia. Aun después del fracaso, la historia puede abrirse a una nueva oportunidad.','Las victorias narradas no autorizan triunfalismo bélico. La frase “la batalla no es vuestra” pertenece a una crisis concreta y no elimina la responsabilidad humana.',ARRAY['Roboam','Asa','Josafat','reforma']::text[],ARRAY['judíos','israelitas']::text[],ARRAY['Jerusalén']::text[]),
  ('2-cronicas-21-28','2CH','section',21,NULL::smallint,28,NULL::smallint,'Declive, mezcla de fidelidad y crisis','Diversos reyes muestran combinaciones de reforma, orgullo, violencia y apostasía, mientras profetas y sacerdotes llaman al arrepentimiento.','Esta unidad se desarrolla dentro del marco histórico general de 2 Crónicas y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 21–28. La obra relee la monarquía desde una perspectiva posterior al exilio. Su audiencia conocía la pérdida del templo y necesitaba comprender continuidad, responsabilidad y esperanza.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Crónicas y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Dentro de los Escritos, Crónicas cierra en muchas ordenaciones del canon hebreo con el decreto de Ciro, abriendo una puerta de regreso y reconstrucción.','La sección ocupa una función definida dentro de la composición de 2 Crónicas. Presenta discursos, oraciones, relatos de batalla, reformas y evaluaciones regias. Omite gran parte del reino del norte salvo cuando se relaciona con Judá.','Advertir que un buen comienzo no garantiza un buen final y que el liderazgo debe permanecer enseñable.','La reforma necesita memoria, enseñanza, justicia y perseverancia. Aun después del fracaso, la historia puede abrirse a una nueva oportunidad.','Las enfermedades o derrotas de personajes concretos no deben usarse para explicar moralmente toda enfermedad o sufrimiento contemporáneo.',ARRAY['Uzías','Jotam','Acaz','orgullo']::text[],ARRAY['judíos','arameos','asirios']::text[],ARRAY['Jerusalén']::text[]),
  ('2-cronicas-29-36','2CH','section',29,NULL::smallint,36,NULL::smallint,'Reformas finales, exilio y decreto de Ciro','Ezequías y Josías impulsan reformas significativas; después, la resistencia de los últimos reyes culmina en destrucción y exilio, seguido por el decreto de Ciro.','Esta unidad se desarrolla dentro del marco histórico general de 2 Crónicas y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 29–36. La obra relee la monarquía desde una perspectiva posterior al exilio. Su audiencia conocía la pérdida del templo y necesitaba comprender continuidad, responsabilidad y esperanza.','En la lectura judía, esta sección contribuye a la memoria canónica de 2 Crónicas y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Dentro de los Escritos, Crónicas cierra en muchas ordenaciones del canon hebreo con el decreto de Ciro, abriendo una puerta de regreso y reconstrucción.','La sección ocupa una función definida dentro de la composición de 2 Crónicas. Presenta discursos, oraciones, relatos de batalla, reformas y evaluaciones regias. Omite gran parte del reino del norte salvo cuando se relaciona con Judá.','Cerrar con juicio y esperanza: la infidelidad tiene consecuencias, pero Dios puede abrir futuro mediante retorno y reconstrucción.','La reforma necesita memoria, enseñanza, justicia y perseverancia. Aun después del fracaso, la historia puede abrirse a una nueva oportunidad.','El exilio no debe interpretarse como abandono absoluto de Dios ni como base para culpar a descendientes por pecados ancestrales sin considerar responsabilidad personal y comunitaria.',ARRAY['Ezequías','Josías','exilio','Ciro']::text[],ARRAY['judíos','babilonios','persas']::text[],ARRAY['Jerusalén','Babilonia']::text[]),
  ('esdras-perfil','EZR','book',1,NULL::smallint,10,NULL::smallint,'Esdras: perfil histórico y literario','Esdras relata etapas del regreso desde Babilonia, la reconstrucción del templo y la misión de Esdras para enseñar la Torá y ordenar la comunidad.','La obra se ubica bajo dominio persa y refleja decretos imperiales, administración provincial, oposición local y la reconstrucción de instituciones judías después del exilio.','Esdras es figura central en la memoria de restauración y enseñanza de la Torá. El libro destaca templo, genealogía, confesión comunitaria y separación frente a prácticas consideradas amenazas al pacto.','Alterna listas, documentos en arameo, narración y oraciones. Se organiza en torno a dos grandes regresos: el de Zorobabel y el de Esdras.','Mostrar que la restauración requiere tanto reconstrucción material como renovación de la enseñanza, el culto y la identidad del pacto.','Recomenzar después de una crisis exige memoria, trabajo colectivo, discernimiento y disposición a corregir prácticas dañinas.','Los capítulos sobre matrimonios mixtos requieren lectura histórica y canónica cuidadosa. No deben usarse para promover racismo, xenofobia ni separación étnica moderna.',ARRAY['regreso','templo','Torá','Esdras','restauración']::text[],ARRAY['judíos','persas','pueblos vecinos']::text[],ARRAY['Babilonia','Jerusalén']::text[]),
  ('esdras-1-3','EZR','section',1,NULL::smallint,3,NULL::smallint,'Regreso y fundamento del templo','Ciro autoriza el regreso, se registran familias y servidores, se restaura el altar y se colocan los fundamentos del templo entre alegría y llanto.','Esta unidad se desarrolla dentro del marco histórico general de Esdras y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–3. La obra se ubica bajo dominio persa y refleja decretos imperiales, administración provincial, oposición local y la reconstrucción de instituciones judías después del exilio.','En la lectura judía, esta sección contribuye a la memoria canónica de Esdras y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Esdras es figura central en la memoria de restauración y enseñanza de la Torá. El libro destaca templo, genealogía, confesión comunitaria y separación frente a prácticas consideradas amenazas al pacto.','La sección ocupa una función definida dentro de la composición de Esdras. Alterna listas, documentos en arameo, narración y oraciones. Se organiza en torno a dos grandes regresos: el de Zorobabel y el de Esdras.','Presentar la restauración como obra comunitaria que combina continuidad, sacrificio, memoria y emociones diversas.','Recomenzar después de una crisis exige memoria, trabajo colectivo, discernimiento y disposición a corregir prácticas dañinas.','Las listas reflejan identidad comunitaria, pero no deben usarse para excluir a personas por falta de linaje documentado en contextos modernos.',ARRAY['Ciro','regreso','altar','fundamento']::text[],ARRAY['judíos','persas']::text[],ARRAY['Babilonia','Jerusalén']::text[]),
  ('esdras-4-6','EZR','section',4,NULL::smallint,6,NULL::smallint,'Oposición y terminación del templo','La obra enfrenta acusaciones y suspensión, pero la predicación profética y la revisión de archivos imperiales permiten completar y dedicar el templo.','Esta unidad se desarrolla dentro del marco histórico general de Esdras y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 4–6. La obra se ubica bajo dominio persa y refleja decretos imperiales, administración provincial, oposición local y la reconstrucción de instituciones judías después del exilio.','En la lectura judía, esta sección contribuye a la memoria canónica de Esdras y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Esdras es figura central en la memoria de restauración y enseñanza de la Torá. El libro destaca templo, genealogía, confesión comunitaria y separación frente a prácticas consideradas amenazas al pacto.','La sección ocupa una función definida dentro de la composición de Esdras. Alterna listas, documentos en arameo, narración y oraciones. Se organiza en torno a dos grandes regresos: el de Zorobabel y el de Esdras.','Mostrar perseverancia, uso responsable de procesos públicos y valor de la palabra profética frente a la oposición.','Recomenzar después de una crisis exige memoria, trabajo colectivo, discernimiento y disposición a corregir prácticas dañinas.','No toda oposición a un proyecto religioso equivale a persecución injusta; el texto debe leerse según sus actores, documentos y contexto específico.',ARRAY['oposición','Hageo','Zacarías','dedicación']::text[],ARRAY['judíos','persas','pueblos vecinos']::text[],ARRAY['Jerusalén']::text[]),
  ('esdras-7-8','EZR','section',7,NULL::smallint,8,NULL::smallint,'Misión de Esdras y segundo regreso','Esdras recibe autorización para enseñar la ley, reúne al grupo de retorno y organiza el viaje con oración, ayuno y responsabilidad sobre recursos.','Esta unidad se desarrolla dentro del marco histórico general de Esdras y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 7–8. La obra se ubica bajo dominio persa y refleja decretos imperiales, administración provincial, oposición local y la reconstrucción de instituciones judías después del exilio.','En la lectura judía, esta sección contribuye a la memoria canónica de Esdras y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Esdras es figura central en la memoria de restauración y enseñanza de la Torá. El libro destaca templo, genealogía, confesión comunitaria y separación frente a prácticas consideradas amenazas al pacto.','La sección ocupa una función definida dentro de la composición de Esdras. Alterna listas, documentos en arameo, narración y oraciones. Se organiza en torno a dos grandes regresos: el de Zorobabel y el de Esdras.','Definir al maestro fiel como quien estudia, practica y enseña, integrando devoción con administración transparente.','Recomenzar después de una crisis exige memoria, trabajo colectivo, discernimiento y disposición a corregir prácticas dañinas.','La autoridad religiosa de Esdras opera dentro de un marco imperial y comunitario; no debe usarse para justificar poder sin rendición de cuentas.',ARRAY['Esdras','Torá','ayuno','enseñanza']::text[],ARRAY['judíos','levitas','persas']::text[],ARRAY['Babilonia','Jerusalén']::text[]),
  ('esdras-9-10','EZR','section',9,NULL::smallint,10,NULL::smallint,'Crisis de matrimonios y confesión','Esdras enfrenta matrimonios con pueblos vecinos, ora en confesión y la comunidad adopta medidas dolorosas para proteger su identidad de pacto.','Esta unidad se desarrolla dentro del marco histórico general de Esdras y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 9–10. La obra se ubica bajo dominio persa y refleja decretos imperiales, administración provincial, oposición local y la reconstrucción de instituciones judías después del exilio.','En la lectura judía, esta sección contribuye a la memoria canónica de Esdras y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Esdras es figura central en la memoria de restauración y enseñanza de la Torá. El libro destaca templo, genealogía, confesión comunitaria y separación frente a prácticas consideradas amenazas al pacto.','La sección ocupa una función definida dentro de la composición de Esdras. Alterna listas, documentos en arameo, narración y oraciones. Se organiza en torno a dos grandes regresos: el de Zorobabel y el de Esdras.','Mostrar la seriedad con que la comunidad percibía su fragilidad religiosa después del exilio y su deseo de corregir compromisos.','Recomenzar después de una crisis exige memoria, trabajo colectivo, discernimiento y disposición a corregir prácticas dañinas.','Este episodio no es una autorización general para divorcio, segregación racial o desprecio al extranjero. Debe leerse junto con Rut y otros textos que integran extranjeros fieles.',ARRAY['confesión','matrimonios mixtos','pacto','separación']::text[],ARRAY['judíos','pueblos vecinos']::text[],ARRAY['Jerusalén']::text[]),
  ('nehemias-perfil','NEH','book',1,NULL::smallint,13,NULL::smallint,'Nehemías: perfil histórico y literario','Nehemías narra la reconstrucción de las murallas de Jerusalén, la organización social y la renovación del pacto bajo liderazgo persa.','El libro se sitúa en el período persa, cuando Jerusalén era una ciudad pequeña y vulnerable dentro de la provincia de Yehud. Nehemías sirve como funcionario y luego gobernador.','Nehemías está unido tradicionalmente a Esdras y destaca memoria, oración, Torá, comunidad, justicia económica y santidad del sábado.','Combina memorias en primera persona, listas, discursos, oraciones y narración comunitaria. El muro funciona como símbolo de seguridad, identidad y responsabilidad.','Mostrar cómo oración, planificación, liderazgo compartido, justicia y enseñanza pueden sostener una comunidad en reconstrucción.','La espiritualidad madura integra devoción, administración, valentía y protección de quienes cargan deudas o trabajos pesados.','El lenguaje contra adversarios no debe usarse para deshumanizar críticos modernos. Las acciones severas de Nehemías deben evaluarse dentro de su contexto y del canon completo.',ARRAY['muralla','Jerusalén','pacto','justicia','Torá']::text[],ARRAY['judíos','persas','samaritanos','amonitas']::text[],ARRAY['Susa','Jerusalén']::text[]),
  ('nehemias-1-3','NEH','section',1,NULL::smallint,3,NULL::smallint,'Llamado, inspección y organización','Nehemías ora, solicita autorización, inspecciona Jerusalén y distribuye el trabajo del muro entre familias y grupos.','Esta unidad se desarrolla dentro del marco histórico general de Nehemías y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–3. El libro se sitúa en el período persa, cuando Jerusalén era una ciudad pequeña y vulnerable dentro de la provincia de Yehud. Nehemías sirve como funcionario y luego gobernador.','En la lectura judía, esta sección contribuye a la memoria canónica de Nehemías y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Nehemías está unido tradicionalmente a Esdras y destaca memoria, oración, Torá, comunidad, justicia económica y santidad del sábado.','La sección ocupa una función definida dentro de la composición de Nehemías. Combina memorias en primera persona, listas, discursos, oraciones y narración comunitaria. El muro funciona como símbolo de seguridad, identidad y responsabilidad.','Modelar liderazgo que combina dolor, oración, análisis, planificación y participación comunitaria.','La espiritualidad madura integra devoción, administración, valentía y protección de quienes cargan deudas o trabajos pesados.','La reconstrucción material no debe convertirse en medida exclusiva de éxito espiritual; el libro mismo avanzará hacia justicia y enseñanza.',ARRAY['Nehemías','muralla','oración','organización']::text[],ARRAY['judíos','persas']::text[],ARRAY['Susa','Jerusalén']::text[]),
  ('nehemias-4-7','NEH','section',4,NULL::smallint,7,NULL::smallint,'Oposición, justicia y terminación del muro','La comunidad enfrenta amenazas externas y una crisis interna de deuda; Nehemías confronta a los nobles y el muro se completa.','Esta unidad se desarrolla dentro del marco histórico general de Nehemías y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 4–7. El libro se sitúa en el período persa, cuando Jerusalén era una ciudad pequeña y vulnerable dentro de la provincia de Yehud. Nehemías sirve como funcionario y luego gobernador.','En la lectura judía, esta sección contribuye a la memoria canónica de Nehemías y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Nehemías está unido tradicionalmente a Esdras y destaca memoria, oración, Torá, comunidad, justicia económica y santidad del sábado.','La sección ocupa una función definida dentro de la composición de Nehemías. Combina memorias en primera persona, listas, discursos, oraciones y narración comunitaria. El muro funciona como símbolo de seguridad, identidad y responsabilidad.','Mostrar que la defensa de la comunidad debe ir acompañada por justicia económica y ejemplo personal del liderazgo.','La espiritualidad madura integra devoción, administración, valentía y protección de quienes cargan deudas o trabajos pesados.','La imagen de trabajar con herramienta y arma pertenece a una situación de amenaza concreta y no autoriza militarizar comunidades religiosas actuales.',ARRAY['oposición','deuda','justicia','muro']::text[],ARRAY['judíos','samaritanos','amonitas']::text[],ARRAY['Jerusalén']::text[]),
  ('nehemias-8-10','NEH','section',8,NULL::smallint,10,NULL::smallint,'Lectura de la Torá y renovación del pacto','Esdras lee la ley, el pueblo celebra, confiesa su historia y firma compromisos comunitarios.','Esta unidad se desarrolla dentro del marco histórico general de Nehemías y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 8–10. El libro se sitúa en el período persa, cuando Jerusalén era una ciudad pequeña y vulnerable dentro de la provincia de Yehud. Nehemías sirve como funcionario y luego gobernador.','En la lectura judía, esta sección contribuye a la memoria canónica de Nehemías y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Nehemías está unido tradicionalmente a Esdras y destaca memoria, oración, Torá, comunidad, justicia económica y santidad del sábado.','La sección ocupa una función definida dentro de la composición de Nehemías. Combina memorias en primera persona, listas, discursos, oraciones y narración comunitaria. El muro funciona como símbolo de seguridad, identidad y responsabilidad.','Enseñar que la renovación surge al comprender la Escritura, recordar la gracia y responder mediante compromisos concretos.','La espiritualidad madura integra devoción, administración, valentía y protección de quienes cargan deudas o trabajos pesados.','“El gozo del Señor” no niega el duelo; aparece después de escucha, llanto, explicación y llamado a compartir con quienes no tienen.',ARRAY['Esdras','Torá','Sukkot','pacto']::text[],ARRAY['judíos','levitas']::text[],ARRAY['Jerusalén']::text[]),
  ('nehemias-11-13','NEH','section',11,NULL::smallint,13,NULL::smallint,'Población, dedicación y reformas finales','Se repuebla Jerusalén, se dedica el muro y Nehemías regresa para corregir abusos relacionados con templo, sábado y alianzas.','Esta unidad se desarrolla dentro del marco histórico general de Nehemías y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 11–13. El libro se sitúa en el período persa, cuando Jerusalén era una ciudad pequeña y vulnerable dentro de la provincia de Yehud. Nehemías sirve como funcionario y luego gobernador.','En la lectura judía, esta sección contribuye a la memoria canónica de Nehemías y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Nehemías está unido tradicionalmente a Esdras y destaca memoria, oración, Torá, comunidad, justicia económica y santidad del sábado.','La sección ocupa una función definida dentro de la composición de Nehemías. Combina memorias en primera persona, listas, discursos, oraciones y narración comunitaria. El muro funciona como símbolo de seguridad, identidad y responsabilidad.','Mostrar que una ceremonia de renovación no sustituye vigilancia continua, administración justa y corrección de recaídas.','La espiritualidad madura integra devoción, administración, valentía y protección de quienes cargan deudas o trabajos pesados.','Las medidas físicas y expulsiones de Nehemías no son un modelo pastoral directo. Deben leerse como acciones de un gobernador antiguo en una crisis de identidad comunitaria.',ARRAY['dedicación','sábado','levitas','reforma']::text[],ARRAY['judíos','levitas']::text[],ARRAY['Jerusalén']::text[]),
  ('ester-perfil','EST','book',1,NULL::smallint,10,NULL::smallint,'Ester: perfil histórico y literario','Ester narra cómo una joven judía llega a ser reina en Persia y, junto con Mardoqueo, enfrenta un decreto de exterminio contra su pueblo.','La historia se ambienta en la corte persa y refleja banquetes, decretos irrevocables, burocracia imperial y vulnerabilidad de una minoría en la diáspora. La identificación exacta de algunos detalles históricos es debatida.','Ester es la base narrativa de Purim y celebra la preservación del pueblo judío en la diáspora. El nombre de Dios no aparece explícitamente en el texto hebreo, pero la providencia se percibe mediante inversiones y coincidencias.','La narración utiliza ironía, banquetes, simetrías, reversos de fortuna y suspenso. Amán asciende y cae, mientras Ester pasa de ocultamiento a intercesión pública.','Fortalecer a comunidades vulnerables mostrando valentía, solidaridad, sabiduría política y preservación en medio de estructuras imperiales peligrosas.','La providencia puede obrar mediante decisiones humanas valientes. El silencio prudente tiene un momento, pero también llega el momento de hablar a favor de quienes están en riesgo.','El final violento requiere atención al contexto de autodefensa y a la retórica de reversión. No debe emplearse para fomentar venganza étnica ni odio contra pueblos actuales.',ARRAY['Ester','Mardoqueo','Amán','Purim','providencia']::text[],ARRAY['judíos','persas']::text[],ARRAY['Susa','Persia']::text[]),
  ('ester-1-2','EST','section',1,NULL::smallint,2,NULL::smallint,'Corte persa y ascenso de Ester','Después de la destitución de Vasti, Ester entra al palacio y llega a ser reina, mientras Mardoqueo descubre una conspiración.','Esta unidad se desarrolla dentro del marco histórico general de Ester y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 1–2. La historia se ambienta en la corte persa y refleja banquetes, decretos irrevocables, burocracia imperial y vulnerabilidad de una minoría en la diáspora. La identificación exacta de algunos detalles históricos es debatida.','En la lectura judía, esta sección contribuye a la memoria canónica de Ester y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Ester es la base narrativa de Purim y celebra la preservación del pueblo judío en la diáspora. El nombre de Dios no aparece explícitamente en el texto hebreo, pero la providencia se percibe mediante inversiones y coincidencias.','La sección ocupa una función definida dentro de la composición de Ester. La narración utiliza ironía, banquetes, simetrías, reversos de fortuna y suspenso. Amán asciende y cae, mientras Ester pasa de ocultamiento a intercesión pública.','Preparar la historia mostrando vulnerabilidad, ocultamiento de identidad y una serie de eventos que luego serán decisivos.','La providencia puede obrar mediante decisiones humanas valientes. El silencio prudente tiene un momento, pero también llega el momento de hablar a favor de quienes están en riesgo.','Vasti y Ester no deben ponerse en competencia moral simplista. El sistema imperial limita la agencia de ambas mujeres y debe reconocerse.',ARRAY['Vasti','Ester','Mardoqueo','palacio']::text[],ARRAY['judíos','persas']::text[],ARRAY['Susa']::text[]),
  ('ester-3-5','EST','section',3,NULL::smallint,5,NULL::smallint,'Decreto de Amán e intercesión de Ester','Amán obtiene un decreto contra los judíos; Mardoqueo llama a Ester a actuar y ella se presenta ante el rey después de ayuno.','Esta unidad se desarrolla dentro del marco histórico general de Ester y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 3–5. La historia se ambienta en la corte persa y refleja banquetes, decretos irrevocables, burocracia imperial y vulnerabilidad de una minoría en la diáspora. La identificación exacta de algunos detalles históricos es debatida.','En la lectura judía, esta sección contribuye a la memoria canónica de Ester y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Ester es la base narrativa de Purim y celebra la preservación del pueblo judío en la diáspora. El nombre de Dios no aparece explícitamente en el texto hebreo, pero la providencia se percibe mediante inversiones y coincidencias.','La sección ocupa una función definida dentro de la composición de Ester. La narración utiliza ironía, banquetes, simetrías, reversos de fortuna y suspenso. Amán asciende y cae, mientras Ester pasa de ocultamiento a intercesión pública.','Mostrar que la posición y el privilegio implican responsabilidad frente al peligro colectivo.','La providencia puede obrar mediante decisiones humanas valientes. El silencio prudente tiene un momento, pero también llega el momento de hablar a favor de quienes están en riesgo.','“Para esta hora” expresa posibilidad y responsabilidad, no una garantía de seguridad personal ni una fórmula para identificar automáticamente el destino de cada individuo.',ARRAY['Amán','decreto','ayuno','intercesión']::text[],ARRAY['judíos','persas']::text[],ARRAY['Susa']::text[]),
  ('ester-6-7','EST','section',6,NULL::smallint,7,NULL::smallint,'Reversión y caída de Amán','El rey recuerda el servicio de Mardoqueo, Amán es obligado a honrarlo y Ester revela el complot durante el segundo banquete.','Esta unidad se desarrolla dentro del marco histórico general de Ester y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 6–7. La historia se ambienta en la corte persa y refleja banquetes, decretos irrevocables, burocracia imperial y vulnerabilidad de una minoría en la diáspora. La identificación exacta de algunos detalles históricos es debatida.','En la lectura judía, esta sección contribuye a la memoria canónica de Ester y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Ester es la base narrativa de Purim y celebra la preservación del pueblo judío en la diáspora. El nombre de Dios no aparece explícitamente en el texto hebreo, pero la providencia se percibe mediante inversiones y coincidencias.','La sección ocupa una función definida dentro de la composición de Ester. La narración utiliza ironía, banquetes, simetrías, reversos de fortuna y suspenso. Amán asciende y cae, mientras Ester pasa de ocultamiento a intercesión pública.','Desarrollar la ironía providencial: la arrogancia prepara su propia caída y la verdad dicha con sabiduría puede cambiar una decisión imperial.','La providencia puede obrar mediante decisiones humanas valientes. El silencio prudente tiene un momento, pero también llega el momento de hablar a favor de quienes están en riesgo.','La ejecución de Amán pertenece al sistema penal del relato y no debe convertirse en celebración ligera de la muerte de un enemigo.',ARRAY['memoria','banquete','reversión','Amán']::text[],ARRAY['judíos','persas']::text[],ARRAY['Susa']::text[]),
  ('ester-8-10','EST','section',8,NULL::smallint,10,NULL::smallint,'Defensa, Purim y memoria comunitaria','Un nuevo decreto permite a los judíos defenderse, la amenaza es revertida y la comunidad establece Purim para recordar la liberación.','Esta unidad se desarrolla dentro del marco histórico general de Ester y concentra los acontecimientos, instituciones y tensiones propios de los capítulos 8–10. La historia se ambienta en la corte persa y refleja banquetes, decretos irrevocables, burocracia imperial y vulnerabilidad de una minoría en la diáspora. La identificación exacta de algunos detalles históricos es debatida.','En la lectura judía, esta sección contribuye a la memoria canónica de Ester y se interpreta en relación con la Torá, el pacto y la experiencia histórica de Israel. Ester es la base narrativa de Purim y celebra la preservación del pueblo judío en la diáspora. El nombre de Dios no aparece explícitamente en el texto hebreo, pero la providencia se percibe mediante inversiones y coincidencias.','La sección ocupa una función definida dentro de la composición de Ester. La narración utiliza ironía, banquetes, simetrías, reversos de fortuna y suspenso. Amán asciende y cae, mientras Ester pasa de ocultamiento a intercesión pública.','Enseñar que la preservación debe convertirse en memoria, solidaridad, generosidad y transmisión intergeneracional.','La providencia puede obrar mediante decisiones humanas valientes. El silencio prudente tiene un momento, pero también llega el momento de hablar a favor de quienes están en riesgo.','Las cifras y escenas de violencia deben leerse en el marco de una minoría amenazada y de la narrativa de reversión, no como licencia para agresión preventiva.',ARRAY['Purim','defensa','memoria','generosidad']::text[],ARRAY['judíos','persas']::text[],ARRAY['Susa','provincias de Persia']::text[])
)
insert into public.biblical_context_units (
  slug, book_code, source_id, scope_kind, chapter_start, verse_start,
  chapter_end, verse_end, title, summary, historical_context, jewish_context,
  literary_context, authorial_intent, theological_reflection,
  interpretive_cautions, key_terms, people_groups, places,
  source_locator, provider_version, content_hash, review_status, enabled, metadata
)
select
  data.slug, data.book_code, source.id, data.scope_kind, data.chapter_start::smallint,
  data.verse_start::smallint, data.chapter_end::smallint, data.verse_end::smallint,
  data.title, data.summary, data.historical_context, data.jewish_context,
  data.literary_context, data.authorial_intent, data.theological_reflection,
  data.interpretive_cautions, data.key_terms, data.people_groups, data.places,
  'vida://corpus/contexto/historicos/v1#' || data.slug,
  'historicos-v1-2026-08-02',
  encode(extensions.digest(
    concat_ws('|', data.slug, data.title, data.summary, data.historical_context,
      data.jewish_context, data.literary_context, data.authorial_intent,
      data.theological_reflection, data.interpretive_cautions),
    'sha256'
  ), 'hex'),
  'approved',
  true,
  jsonb_build_object(
    'coverage_batch', 'historical-books',
    'generated_by_ai', true,
    'review_level', 'project-editorial'
  )
from data cross join source
on conflict (slug) do update set
  book_code = excluded.book_code,
  source_id = excluded.source_id,
  scope_kind = excluded.scope_kind,
  chapter_start = excluded.chapter_start,
  verse_start = excluded.verse_start,
  chapter_end = excluded.chapter_end,
  verse_end = excluded.verse_end,
  title = excluded.title,
  summary = excluded.summary,
  historical_context = excluded.historical_context,
  jewish_context = excluded.jewish_context,
  literary_context = excluded.literary_context,
  authorial_intent = excluded.authorial_intent,
  theological_reflection = excluded.theological_reflection,
  interpretive_cautions = excluded.interpretive_cautions,
  key_terms = excluded.key_terms,
  people_groups = excluded.people_groups,
  places = excluded.places,
  source_locator = excluded.source_locator,
  provider_version = excluded.provider_version,
  content_hash = excluded.content_hash,
  review_status = excluded.review_status,
  enabled = excluded.enabled,
  metadata = excluded.metadata,
  updated_at = now();

update public.biblical_books
set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
  'coverage_status', 'context_ready',
  'coverage_batch', 'historical-books',
  'coverage_version', 'historicos-v1-2026-08-02'
), updated_at = now()
where code in ('JOS','JDG','RUT','1SA','2SA','1KI','2KI','1CH','2CH','EZR','NEH','EST');
